ALTER TABLE tenants ADD COLUMN revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE tenants ADD COLUMN paused INTEGER NOT NULL DEFAULT 0 CHECK(paused IN (0,1));
ALTER TABLE tenants ADD COLUMN cutoff_min INTEGER NOT NULL DEFAULT 60 CHECK(cutoff_min BETWEEN 0 AND 10080);
ALTER TABLE tenants ADD COLUMN horizon_days INTEGER NOT NULL DEFAULT 60 CHECK(horizon_days BETWEEN 1 AND 180);
ALTER TABLE tenants ADD COLUMN logo_url TEXT;
ALTER TABLE tenants ADD COLUMN review_url TEXT;
ALTER TABLE tenants ADD COLUMN marketing_enabled INTEGER NOT NULL DEFAULT 0;
ALTER TABLE tenants ADD COLUMN reminders_enabled INTEGER NOT NULL DEFAULT 1;
ALTER TABLE tenants ADD COLUMN loyalty_bps INTEGER NOT NULL DEFAULT 0 CHECK(loyalty_bps IN (0,100,200));
ALTER TABLE tenants ADD COLUMN loyalty_cap INTEGER NOT NULL DEFAULT 10000 CHECK(loyalty_cap>=0);
ALTER TABLE tenants ADD COLUMN loyalty_min_redeem INTEGER NOT NULL DEFAULT 0 CHECK(loyalty_min_redeem>=0);
ALTER TABLE tenants ADD COLUMN loyalty_expiry_days INTEGER NOT NULL DEFAULT 0 CHECK(loyalty_expiry_days BETWEEN 0 AND 730);
CREATE TABLE merchant_users(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('owner','staff')), active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,id));
CREATE TABLE magic_links(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES merchant_users(id), expires_at INTEGER NOT NULL, used_at INTEGER);
CREATE TABLE sessions(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES merchant_users(id), expires_at INTEGER NOT NULL, magic_hash TEXT NOT NULL REFERENCES magic_links(hash));
CREATE TRIGGER consume_magic BEFORE INSERT ON sessions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM magic_links WHERE hash=NEW.magic_hash AND user_id=NEW.user_id AND used_at IS NULL AND expires_at>unixepoch()*1000) THEN RAISE(ABORT,'invalid_magic') END; UPDATE magic_links SET used_at=unixepoch()*1000 WHERE hash=NEW.magic_hash; END;
CREATE TABLE audit_log(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), actor TEXT NOT NULL, action TEXT NOT NULL, subject TEXT, created_at INTEGER NOT NULL);
CREATE TABLE rate_limits(key TEXT PRIMARY KEY, window INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE TABLE mock_mail(id TEXT PRIMARY KEY, recipient TEXT NOT NULL, token TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE services(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, duration_min INTEGER NOT NULL CHECK(duration_min BETWEEN 5 AND 240 AND duration_min%5=0), buffer_min INTEGER NOT NULL DEFAULT 0 CHECK(buffer_min BETWEEN 0 AND 60 AND buffer_min%5=0), price_centimes INTEGER NOT NULL CHECK(price_centimes BETWEEN 0 AND 10000000), active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,id));
CREATE TABLE resources(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, UNIQUE(tenant_id,id));
CREATE TABLE service_resources(tenant_id TEXT NOT NULL, service_id TEXT NOT NULL, resource_id TEXT NOT NULL, PRIMARY KEY(tenant_id,service_id,resource_id), FOREIGN KEY(tenant_id,service_id) REFERENCES services(tenant_id,id), FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE weekly_hours(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, resource_id TEXT NOT NULL, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6), start_min INTEGER NOT NULL CHECK(start_min BETWEEN 0 AND 1435 AND start_min%5=0), end_min INTEGER NOT NULL CHECK(end_min BETWEEN 5 AND 1440 AND end_min%5=0 AND end_min>start_min), FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE blackouts(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), resource_id TEXT, starts_at INTEGER NOT NULL, ends_at INTEGER NOT NULL CHECK(ends_at>starts_at), FOREIGN KEY(tenant_id,resource_id) REFERENCES resources(tenant_id,id));
CREATE TABLE tenant_subscription_status(tenant_id TEXT PRIMARY KEY REFERENCES tenants(id), plan TEXT NOT NULL DEFAULT 'pilot', status TEXT NOT NULL DEFAULT 'trial' CHECK(status IN ('trial','active','past_due','cancelled')), billing_provider TEXT NOT NULL DEFAULT 'disabled', period_end INTEGER);
CREATE INDEX hours_lookup ON weekly_hours(tenant_id,resource_id,weekday);
CREATE INDEX blackouts_lookup ON blackouts(tenant_id,starts_at,ends_at);
